import {MovieStage} from './cinematic.js';
import {encodeMovieFrames} from './video-encoder.js';
import {movieChapters,movieState,movieDimensions,movieFilename,normalizeMovieOptions} from './movie.js';
const clock=t=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;
export function initMovieUI(api,{StageClass=MovieStage,encode=encodeMovieFrames}={}){
 let closeActive=()=>{};
 async function open(){
  closeActive();const project=structuredClone(api.project());let options=normalizeMovieOptions(project.movie),stage=null,exportStage=null,controller=null,disposed=false,busy=false,playing=false,raf=0,last=0,time=0,generation=0,url=null,ready=false;
  const field=(label,name,values)=>`<label>${label}<select name="${name}">${values.map(([v,label])=>`<option value="${v}"${String(options[name])===String(v)?' selected':''}>${label}</option>`).join('')}</select></label>`;
  const number=(label,name,min,max,step)=>`<label>${label}<input name="${name}" type="number" value="${options[name]}" min="${min}" max="${max}" step="${step}" required></label>`;
  api.openModal('Create an MP4 presentation',`<div id="moviePanel"><p>A complete product reveal, from a closed assembly to a polished final view.</p><div class="movie-layout"><section class="movie-main" aria-label="Presentation preview"><div class="movie-screen"><canvas id="movieCanvas" width="960" height="540" aria-label="3D presentation preview"></canvas><div id="movieLoading" class="movie-loading">Preparing studio lighting…</div></div><div class="movie-transport"><button id="moviePlay" disabled>Play preview</button><button id="movieReset" disabled>Restart</button><output id="movieTime">0:00 / ${clock(options.duration)}</output></div><label class="movie-scrub">Presentation timeline<input id="movieScrub" type="range" min="0" max="${options.duration}" step=".05" value="0" disabled></label><div id="movieChapters" class="movie-chapters" aria-label="Presentation chapters"></div><p id="movieChapter" class="movie-current" aria-live="off">Closed assembly</p></section><form id="movieSettings" class="movie-settings"><span class="eyebrow">Presentation settings</span>${number('Duration · seconds','duration',20,60,1)}<div class="fields two">${field('Resolution','resolution',[['1080','1080p · Full HD'],['720','720p · HD']])}${field('Frame rate','fps',[[30,'30 fps'],[24,'24 fps']])}</div>${field('Render quality','quality',[['high','High · supersampled'],['standard','Standard · faster']])}${field('Studio background','background',[['warm','Warm ivory'],['white','Clean white'],['dark','Charcoal']])}<details><summary>Composition</summary><div class="stack">${number('Exploded spacing','explosion',.4,2,.1)}${number('Enclosure opacity during reveal','ghostOpacity',.04,.35,.01)}${number('Camera elevation · degrees','elevation',10,65,1)}<label class="check"><input name="includeHidden" type="checkbox"${options.includeHidden?' checked':''}>Include hidden physical parts</label></div></details><p class="fine">Starts from placed positions, with all enabled enclosure panels closed. Keep-outs and joint playback are excluded. Harnesses appear in assembled views and hide during the explosion.</p></form></div><div id="movieError" class="movie-error" role="alert" hidden></div><div class="movie-export-bar"><button id="movieExport" class="primary" disabled>Render MP4</button><button id="movieCancel" hidden>Cancel export</button><span id="movieStatus" role="status">Preparing preview…</span></div><progress id="movieProgress" max="1" value="0" aria-label="MP4 export progress" hidden></progress><p class="fine">Silent H.264 MP4. High quality adds sharper edges and finer shadows. Keep this tab open during rendering; the saved movie always contains every frame. Detailed models and surface artwork give the most realistic results.</p><section id="movieResult" class="movie-result" hidden><div class="movie-result-head"><strong>Your presentation is ready</strong><a id="movieDownload" class="movie-download">Download MP4</a></div><video id="movieVideo" controls playsinline preload="metadata" aria-label="Exported MP4 presentation"></video><p id="movieResultInfo" class="fine"></p></section></div>`);
  const modal=document.querySelector('#modal'),panel=document.querySelector('#moviePanel'),$=s=>panel.querySelector(s),form=$('#movieSettings');modal.classList.add('movie-modal');
  const fail=e=>{if(disposed)return;$('#movieError').textContent=e.message||String(e);$('#movieError').hidden=false;};
  const clearError=()=>{$('#movieError').hidden=true;$('#movieError').textContent='';};
  function controls(){for(const el of form.querySelectorAll('input,select'))el.disabled=busy;$('#movieExport').disabled=busy||!ready;$('#moviePlay').disabled=busy||!ready;$('#movieReset').disabled=busy||!ready;$('#movieScrub').disabled=busy||!ready;for(const b of $('#movieChapters').querySelectorAll('button'))b.disabled=busy||!ready;$('#movieCancel').hidden=!busy;}
  function pause(){playing=false;cancelAnimationFrame(raf);$('#moviePlay').textContent='Play preview';}
  function showTime(t){time=Math.max(0,Math.min(options.duration,t));$('#movieScrub').value=time;$('#movieTime').textContent=`${clock(time)} / ${clock(options.duration)}`;const state=movieState(time,options);$('#movieChapter').textContent=state.name;for(const b of $('#movieChapters').querySelectorAll('button'))b.setAttribute('aria-current',Number(b.dataset.chapter)===state.index?'step':'false');}
  function draw(t){showTime(t);stage?.render(time);}
  function chapters(){$('#movieChapters').innerHTML=movieChapters(options.duration).map((c,i)=>`<button type="button" data-chapter="${i}" title="Jump to ${c.name}"><small>${clock(c.start)}</small>${c.name}</button>`).join('');for(const b of $('#movieChapters').querySelectorAll('button'))b.onclick=()=>{pause();draw(movieChapters(options.duration)[Number(b.dataset.chapter)].start);};$('#movieScrub').max=options.duration;}
  function clearResult(){const video=$('#movieVideo');try{video.pause();}catch{}video.removeAttribute('src');try{video.load();}catch{}if(url)URL.revokeObjectURL(url);url=null;$('#movieDownload').removeAttribute('href');$('#movieResult').hidden=true;}
  function close(){if(disposed)return;disposed=true;generation++;pause();controller?.abort();stage?.dispose();stage=null;exportStage?.dispose();exportStage=null;clearResult();observer?.disconnect();modal.removeEventListener('close',close);modal.classList.remove('movie-modal');}
  const observer=typeof MutationObserver==='undefined'?null:new MutationObserver(()=>{if(!panel.isConnected)close();});observer?.observe(document.querySelector('#modalBody'),{childList:true});modal.addEventListener('close',close);closeActive=close;
  async function buildPreview(){
   const own=++generation;pause();ready=false;stage?.dispose();stage=null;controls();$('#movieLoading').hidden=false;$('#movieLoading').textContent='Preparing studio lighting…';let next;
   // A fresh canvas is required after disposing a WebGL context.
   const canvas=document.createElement('canvas');canvas.id='movieCanvas';canvas.setAttribute('aria-label','3D presentation preview');$('#movieCanvas').replaceWith(canvas);
   try{next=new StageClass(project,options,canvas,{preview:true});next.setSize(960,540);await next.ready();if(disposed||own!==generation){next.dispose();return;}stage=next;ready=true;draw(Math.min(time,options.duration));$('#movieLoading').hidden=true;$('#movieStatus').textContent='Preview ready · rendered locally';}
   catch(e){next?.dispose();if(disposed||own!==generation)return;$('#movieLoading').textContent='Preview unavailable';$('#movieStatus').textContent='Adjust settings or reload to try again.';fail(e);}finally{if(!disposed&&own===generation)controls();}
  }
  function readOptions(){const raw={};for(const key of Object.keys(options)){const el=form.elements?.namedItem(key)||form.querySelector(`[name="${key}"]`);raw[key]=el.type==='checkbox'?el.checked:['duration','fps','explosion','ghostOpacity','elevation'].includes(key)?Number(el.value):el.value;}return normalizeMovieOptions(raw);}
  form.onsubmit=e=>e.preventDefault();form.onchange=async()=>{if(busy)return;clearError();try{const next=readOptions();api.commit(()=>api.project().movie=next,{rebuild:false,inspector:false});options=next;clearResult();chapters();await buildPreview();}catch(e){ready=false;controls();fail(e);}};
  $('#moviePlay').onclick=()=>{if(playing){pause();return;}if(time>=options.duration)time=0;playing=true;last=performance.now();$('#moviePlay').textContent='Pause';const tick=now=>{if(!playing||disposed)return;try{draw(time+(now-last)/1000);last=now;if(time>=options.duration){pause();return;}raf=requestAnimationFrame(tick);}catch(e){pause();fail(e);}};raf=requestAnimationFrame(tick);};
  $('#movieReset').onclick=()=>{pause();draw(0);};$('#movieScrub').oninput=()=>{pause();draw(Number($('#movieScrub').value));};
  $('#movieCancel').onclick=()=>{controller?.abort();$('#movieCancel').disabled=true;$('#movieStatus').textContent='Cancelling…';};
  $('#movieExport').onclick=async()=>{
   if(disposed||busy||!ready)return;clearError();pause();clearResult();busy=true;controller=new AbortController();const signal=controller.signal;controls();$('#movieCancel').disabled=false;$('#movieProgress').hidden=false;$('#movieProgress').value=0;$('#movieStatus').textContent='Preparing full-resolution scene…';const started=performance.now();let lastProgress=0;
   try{
    const {width,height}=movieDimensions(options),scale=options.quality==='high'?2:1,canvas=document.createElement('canvas'),output=document.createElement('canvas');output.width=width;output.height=height;const ctx=output.getContext('2d',{willReadFrequently:true,alpha:false});if(!ctx)throw Error('This browser could not prepare movie frames.');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';
    stage?.dispose();stage=null;canvas.id='movieCanvas';canvas.setAttribute('aria-label','Rendering MP4 frames');$('#movieCanvas').replaceWith(canvas);exportStage=new StageClass(project,options,canvas);exportStage.setSize(width*scale,height*scale);await exportStage.ready();if(signal.aborted)throw new DOMException('Movie export cancelled.','AbortError');
    const blob=await encode({options,signal,renderFrame:t=>{exportStage.render(t);ctx.drawImage(canvas,0,0,width,height);return ctx.getImageData(0,0,width,height).data;},onProgress:p=>{if(disposed)return;$('#movieProgress').value=p.progress;if(performance.now()-lastProgress>200||p.progress===1){lastProgress=performance.now();const elapsed=(lastProgress-started)/1000,remaining=p.progress>.03?Math.ceil(elapsed*(1-p.progress)/p.progress):null;showTime(p.time);$('#movieStatus').textContent=p.progress===1?'Finalizing MP4…':`${Math.floor(p.progress*100)}% · ${movieState(p.time,options).name}${remaining===null?'':` · about ${clock(remaining)} left`}`;}}});
    if(signal.aborted||disposed)throw new DOMException('Movie export cancelled.','AbortError');url=URL.createObjectURL(blob);$('#movieVideo').src=url;$('#movieDownload').href=url;$('#movieDownload').download=movieFilename(project.title);$('#movieResultInfo').textContent=`${width} × ${height} · ${options.fps} fps · ${options.duration} seconds · ${(blob.size/1048576).toFixed(1)} MB`;$('#movieResult').hidden=false;$('#movieStatus').textContent='MP4 ready to download';api.notify('MP4 presentation is ready.');
   }catch(e){if(!disposed){if(e.name==='AbortError')$('#movieStatus').textContent='Export cancelled. Your assembly is unchanged.';else{$('#movieStatus').textContent='Export failed. Try 720p / Standard quality.';fail(e);}}}
   finally{exportStage?.dispose();exportStage=null;controller=null;busy=false;if(!disposed){$('#movieProgress').hidden=true;const status=$('#movieStatus').textContent;await buildPreview();if(!disposed&&ready)$('#movieStatus').textContent=status;}}
  };
  chapters();await buildPreview();
 }
 return {open,close(){closeActive();if(document.querySelector('#moviePanel'))document.querySelector('#modal').close();}};
}
